#!/usr/bin/env python3
"""
Phase 7 - write models/xgboost_v1/model_card.md from the saved checkpoint files and reports, so every number in the card is the number in the files.
Run after train.py, check_preprocessing.py, compare_default.py and seed_noise.py:   python src/training/make_model_card.py
"""
import json
import sys
from pathlib import Path

import pandas as pd

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "src" / "common"))
sys.path.insert(0, str(ROOT / "src" / "features"))
sys.path.insert(0, str(Path(__file__).resolve().parent))
import engineering as en  # noqa: E402
import lmis_data as ld  # noqa: E402
import splits as sp  # noqa: E402
import tune  # noqa: E402

M = ROOT / "models" / "xgboost_v1"
R = ROOT / "reports" / "training"
J = lambda p: json.load(open(p))  # noqa: E731
HYPER = [("objective", "Loss function. Squared error on the log change; large errors are not down-weighted"),
         ("tree_method", "Histogram split finding (multi-core)"),
         ("grow_policy", "Leaf-wise growth: always split the leaf with the largest gain, up to max_leaves"),
         ("max_depth", "0 = no depth limit; complexity is limited by max_leaves instead"),
         ("max_leaves", "Leaves per tree. Fewer leaves = smoother, more regularised trees"),
         ("learning_rate", "Shrinkage applied to each tree's contribution"),
         ("n_estimators", "Number of trees (chosen by the cross-validation checkpoints, see Section 6)"),
         ("min_child_weight", "Minimum summed Hessian in a leaf = minimum number of training rows in a leaf for squared error"),
         ("reg_lambda", "L2 penalty on leaf values"),
         ("reg_alpha", "L1 penalty on leaf values"),
         ("gamma", "Minimum loss reduction needed to make a split (on the squared-error scale of the log change)"),
         ("subsample", "Fraction of rows sampled for each tree"),
         ("colsample_bytree", "Fraction of features sampled for each tree"),
         ("colsample_bynode", "Fraction of features sampled at each split"),
         ("max_bin", "Histogram bins per feature"),
         ("n_jobs", "CPU threads (-1 = all cores)"),
         ("verbosity", "Silent")]


def f(v, nd=3):
    if isinstance(v, bool):
        return str(v)
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return f"{v:g}" if abs(v) < 1e4 and (v == round(v, 4)) else f"{v:.{nd}f}"
    return str(v)


def table(header, rows):
    out = ["| " + " | ".join(header) + " |", "|" + "|".join("---" for _ in header) + "|"]
    out += ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]
    return "\n".join(out)


def main():
    params, man, met = J(M / "params.json"), J(M / "checkpoint_manifest.json"), J(R / "validation_metrics.json")
    split, itv = J(sp.MANIFEST), J(M / "intervals.json")
    dflt, pre_chk, noise = J(R / "default_vs_tuned.json"), J(R / "preprocessing_check.json"), J(R / "seed_noise.json")
    best = {k: J(R / f"tune_{k}_best.json") for k in "EVS"}
    stage1 = {k: J(R / f"tune_{k}_stage1_best.json") for k in "EVS"}
    trials = {k: pd.read_csv(R / f"tune_{k}_trials.csv") for k in "EVS"}
    curves = J(R / "learning_curves.json")
    prep = J(M / "preprocessor.json")
    spec = ld.spec()
    W = split["windows"]
    n_trials = {k: len(trials[k]) for k in "EVS"}
    P = {k: params[k]["xgboost_params"] for k in "EVS"}
    L = []
    add = L.append
    add("# Model card: XGBoost labour-market forecaster (`xgboost_v1`)\n")
    add("*Generated by `src/training/make_model_card.py` from the files in this folder and in `reports/training/`; do not edit by hand.*\n")
    add("## 1. Summary\n")
    add("Three gradient-boosted tree models (XGBoost %s), one for each of employed workers (E), job vacancies (V) and registered seekers (S), forecast the log change of a district-sector series "
        "1 to 12 months ahead. Each model is a mean of %d random-seed fits. The models were trained on the train split only (target months %s to %s, %s rows), "
        "checked on a separate validation split (%s to %s, %s rows), and never saw the test split. This card describes the Phase 7 deliverable; the final test evaluation is Phase 8.\n"
        % (man["environment"]["xgboost"], len(params["E"]["seeds"]), split["files"]["train"]["target_range"][0], split["files"]["train"]["target_range"][1], f"{split['files']['train']['rows']:,}",
           W["validation"]["first_month"][:7], W["validation"]["last_month"][:7], f"{split['files']['validation']['rows']:,}"))
    add(table(["Target", "Validation WAPE %", "Same rows: last value + seasonal shift", "Improvement", "Phase 6 default settings, same pipeline"],
              [(f"{ld.NAMES[k]} ({k})", f"{met[k]['validation_wape_mean_horizon']:.2f}", f"{met[k]['baselines']['last_plus_seasonal_shift']['mean_horizon']:.2f}",
                f"{100 * (1 - met[k]['validation_wape_mean_horizon'] / met[k]['baselines']['last_plus_seasonal_shift']['mean_horizon']):.0f}%",
                f"{dflt[k]['phase6_default_validation_wape']:.2f}") for k in "EVS"]))
    add("\nWAPE = sum of absolute count errors / sum of actual counts, averaged with equal weight over the horizons present in validation (1 to 10). Seekers are scored without excluding "
        "any month; their validation window lies inside the e-Shram registration ramp (see Section 9).\n")

    add("## 2. Intended use and limits\n")
    add("* **Use:** monthly district-sector forecasts of employment, vacancies and registered seekers for the labour-market dashboard and the skill demand-supply gap (SIH26246), after the Phase 8 test evaluation and sign-off.\n"
        "* **Not for:** decisions about individuals, districts or sectors outside the 56 districts x 5 sectors, or horizons beyond 12 months. The data are synthetic (generated to mimic official statistics), so accuracy here says "
        "how well the method works on this simulator, not on real data.\n"
        "* **No real forecasts yet:** this phase produces and validates the model; no forecast has been published.\n")

    add("## 3. Data and splits\n")
    add("Source: `data/processed/panel_monthly.parquet` (56 districts x 5 sectors = 280 series x 192 months, 2011-01 to 2026-12). The file `data/splits/{train,validation,test}.parquet` "
        "(built by `src/splits/make_splits.py`, checksums in `data/splits/split_manifest.json`) holds one row per series, forecast origin and horizon.\n")
    add(table(["Split", "Calendar window", "Months", "Share of calendar", "Rows", "Origin rule"],
              [("train", f"{W['train']['first_month'][:7]} to {W['train']['last_month'][:7]}", W["train"]["months"], f"{100 * W['train']['share']:.1f}%", f"{split['files']['train']['rows']:,}", "origin on or after 2014-01 (36 months of history), so train targets run from 2014-02"),
               ("validation", f"{W['validation']['first_month'][:7]} to {W['validation']['last_month'][:7]}", W["validation"]["months"], f"{100 * W['validation']['share']:.1f}%", f"{split['files']['validation']['rows']:,}", "origin on or after the last train month, so the longest horizon is 10"),
               ("test (locked)", f"{W['test']['first_month'][:7]} to {W['test']['last_month'][:7]}", W["test"]["months"], f"{100 * W['test']['share']:.1f}%", f"{split['files']['test']['rows']:,}", "origin on or after the last validation month; not read in this phase")]))
    add("\n* **Time-aware, not random.** The autocorrelated series are split into consecutive blocks of calendar time with the same cut dates for every series. A random or per-row stratified split "
        "would put neighbouring months in different splits and leak the future into training.\n"
        "* **Balanced by sector by construction.** Every sector has 56 series and therefore the same %d / %d / %d months and the same number of rows in each split "
        "(checked in `tests/test_splits.py`). Rows are assigned by target month, so the three files have disjoint targets in time order; %s rows that straddle a boundary without satisfying the origin rule are dropped.\n"
        "* **Independent files.** The train and validation files can be rebuilt exactly from a panel that stops at the end of their window (`tests/test_splits.py`). Features of a validation row may look back into the train period (that is history, known at the forecast origin), never forward.\n"
        "* **Shock handling.** Employed-worker training rows whose window (12 months before the origin to the target month) touches COVID (2020-03 to 2022-02) or the 2016-17 policy spans are removed (%s of the %s train rows remain for E). "
        "Vacancy and seeker models train on all rows (Phase 5 policy). Scoring excludes target months inside those shocks for E and V; the validation window (2022-03 on) is clear of them. Seekers are scored on all months.\n"
        "* **Phase 5/6 exposure.** Features, base choices and the model family were selected in Phases 5-6 with folds that used 2018, 2019 and 2024 as validation years. The new test window (2023-2026) therefore contains 2023 and 2024 months that influenced those choices, and 2025-26 was scored once by the quarantined prototype. Phase 8 must say so.\n"
        % (W["train"]["months"], W["validation"]["months"], W["test"]["months"], f"{split['rows_dropped_straddling_boundaries']:,}", f"{prep['E']['n_rows']:,}", f"{split['files']['train']['rows']:,}"))

    add("## 4. Model architecture\n")
    add("* **Family:** gradient-boosted decision trees (XGBoost `XGBRegressor`, `tree_method='hist'`, leaf-wise growth). Chosen in Phase 6 (tied with scikit-learn HistGradientBoosting; 0.59 points better than the best baseline pooled).\n"
        "* **One global model per target** (E, V, S) across all 280 series. **Direct multi-horizon:** the horizon (1-12) is an input feature, so one model answers every horizon; no recursive forecasting.\n"
        "* **Prediction target:** the log change `log(value at t+h) - log(base at t)`, with base = last value (E), mean of the last 3 months (V) or last 6 months (S) (Phase 5 choice). Predicted count = exp(base + predicted change).\n"
        "* **Ensemble:** the saved model for each target is the mean of the predicted changes of %d XGBoost models trained with seeds %s (they differ in row and feature sampling). One fit moves by %.1f-%.1f%% of its validation WAPE across seeds (Section 7); averaging removes most of that.\n"
        "* **Lag and rolling features** (all trailing, built only from months at or before the forecast origin; verified by a truncation test in `tests/test_features.py`): momentum = log change over the last 1, 3, 6, 12 and 36 months; "
        "deviation of the current level from its 3-, 6- and 12-month rolling means; 12-month rolling volatility of monthly changes; sector-wide aggregates of the same quantities; "
        "a trailing seasonal profile and the seasonal change expected between the origin month and the target month; the value one year before the target; calendar month of origin and target.\n"
        % (len(params["E"]["seeds"]), params["E"]["seeds"], min(noise[k]["seed_std_pct_of_mean"] for k in "EVS"), max(noise[k]["seed_std_pct_of_mean"] for k in "EVS")))
    groups = {}
    rows = []
    for k in "EVS":
        g = {}
        for name in spec[k]["features"]:
            g.setdefault(en.group_of(name, k), []).append(name)
        groups[k] = g
        rows.append((f"{ld.NAMES[k]} ({k})", len(spec[k]["features"]), spec[k]["base"], "yes" if spec[k]["mask_shock_windows"] else "no"))
    add(table(["Target", "Features", "Base", "Shock windows removed from training"], rows))
    add("")
    for k in "EVS":
        add(f"<details><summary>{ld.NAMES[k]} ({k}): the {len(spec[k]['features'])} features by group</summary>\n")
        for g, names in sorted(groups[k].items()):
            add(f"* **{g}** ({len(names)}): " + ", ".join(f"`{n}`" for n in names))
        add("\n</details>\n")

    add("## 5. Preprocessing (fitted on the train split only)\n")
    add("`src/training/preprocess.py`, stored in `preprocessor.json`. `fit` refuses any rows that are not labelled `train`; validation, test and new data are only transformed (`tests/test_training.py`).\n"
        "1. **Missing values:** replaced by the training median of each feature. The train split has %d missing values (the 36-month history requirement removes them), so this is a safeguard for new data.\n"
        "2. **Scaling:** continuous features are standardised with the training mean and standard deviation; horizon and calendar codes are left as they are.\n"
        "3. **Effect on this model:** none that matters. Trees split on thresholds, so scaling does not change what they can learn. Refitting without preprocessing changes validation WAPE by %s points for E, %s for V and %s for S (`reports/training/preprocessing_check.json`). "
        "The step is kept because it was required, it costs nothing, and the same pipeline can feed linear or neural challengers.\n"
        % (prep["E"]["n_missing_in_fit"], f"{pre_chk['E']['difference_points']:+.3f}", f"{pre_chk['V']['difference_points']:+.3f}", f"{pre_chk['S']['difference_points']:+.3f}"))

    add("## 6. Hyper-parameters and how they were chosen\n")
    add("### 6.1 Final values\n")
    rows = []
    for key, why in HYPER:
        rows.append((f"`{key}`", *[f(P[k].get(key, "")) for k in "EVS"], why))
    add(table(["Parameter", "E", "V", "S", "Meaning"], rows))
    add(f"\nSeeds of the five-model ensemble: {params['E']['seeds']} (`random_state` above is the base value; each ensemble member overrides it). The Phase 6 default was: learning rate 0.08, 250 trees, 31 leaves, min_child_weight 100, "
        "lambda 5, alpha 0, gamma 0, subsample 0.8, colsample_bytree 0.8, 256 bins.\n")
    add("### 6.2 Regularisation methods in use\n")
    add("* **Shrinkage and early stopping of the tree count:** a low learning rate and a tree count chosen at the best cross-validation checkpoint, not the maximum.\n"
        "* **Leaf-size limits:** `max_leaves` and `min_child_weight` (at least that many rows per leaf) stop trees fitting single districts.\n"
        "* **Penalties:** `reg_lambda` (L2) shrinks leaf values; `reg_alpha` (L1) and `gamma` (minimum split gain) were searched and are kept only where the search chose them (E uses only a tiny gamma, V a small alpha and gamma, S none).\n"
        "* **Stochastic sampling:** `subsample`, `colsample_bytree` and `colsample_bynode` give each tree a different view of rows and features.\n"
        "* **Seed averaging:** five models per target.\n"
        "* **Data-side:** shock windows removed from E training; time-ordered folds only; detrended features (time-proxy features were excluded in Phase 5).\n")
    add("### 6.3 Search procedure (iterative)\n")
    add("**Validation scheme.** Rolling-origin (expanding window) folds inside the train split: train on targets up to 2016-12 and score the next 12 target months (origins on or after the cut-off), then the same for cut-offs 2017-12 and 2018-12. "
        "Score = WAPE on counts, equal weight for horizons 1-12. Preprocessing is refitted on every fold's training rows.\n")
    sp_rows = [(a, ", ".join(f(x) for x in v)) for a, v in tune.SPACE.items()]
    add(table(["Searched parameter", "Values tried"], sp_rows))
    add("")
    st_rows = []
    for k in "EVS":
        T = trials[k]
        d = T.iloc[0]
        top = T.nsmallest(1, "cv_wape").iloc[0]
        c = best[k]["chosen"]
        st_rows.append((f"{ld.NAMES[k]} ({k})", f"{d.cv_wape:.3f} ({int(d.best_trees)} trees)", f"{top.cv_wape:.3f} (trial {int(top.trial)})", n_trials[k],
                        f"{c['name']}", f"{c['cv_wape']:.3f}", f"{met[k]['validation_wape_mean_horizon']:.3f}", f"{c['relative_score']:.3f}"))
    add(table(["Target", "CV WAPE, Phase 6 default", "CV WAPE, best of search", "Trials", "Final choice", "Its CV WAPE", "Validation WAPE of the saved checkpoint", "Four-fold score (default = 1)"], st_rows))
    add("\n1. **Stage 1, search on the three rolling-origin folds:** the Phase 6 default plus 40 random configurations, then 18 local variations around the three best (one seed each). Gains over the default were small: "
        + ", ".join(f"{k} {100 * (1 - trials[k].cv_wape.min() / trials[k].iloc[0].cv_wape):.1f}%" for k in "EVS") + " better cross-validation WAPE.\n"
        "2. **Stage 1 shortlist:** configurations within 1%% of the best were refitted on the whole train split and scored on validation. A single fit moved by 1-2%% between seeds and also between thread counts (Section 7), "
        "which is larger than the gaps between shortlisted configurations, so these were scored as five-seed averages.\n"
        "3. **Stage 2, add the most recent era:** the folds above are all calm pre-COVID years. Scoring the Phase 6 default on validation showed it beating the stage-1 pick for seekers by a wide margin "
        "(%.2f vs %.2f) and slightly for E (%.2f vs %.2f), with V level. Stage 2 therefore treats the validation split as a fourth, most recent fold: the 12 best configurations by cross-validation and the default (at its cross-validated and at its Phase 6 tree count) are scored on all four folds, "
        "each fold's WAPE is divided by the default's WAPE on that fold, and the average of the four ratios decides. For E and V the winner is a tuned configuration, by %.1f%% and %.1f%% over the default (inside the noise); for S the default is not beaten, so it is kept. Stage-2 validation scores are 3-seed averages and differ from the saved 5-seed checkpoints by up to %.2f points, which is the noise level.\n"
        % (stage1["S"]["chosen"]["val_wape"], dflt["S"]["phase6_default_validation_wape"], stage1["E"]["chosen"]["val_wape"], dflt["E"]["phase6_default_validation_wape"],
           100 * (1 - best["E"]["chosen"]["relative_score"]), 100 * (1 - best["V"]["chosen"]["relative_score"]),
           max(abs(best[k]["chosen"]["val_wape"] - met[k]["validation_wape_mean_horizon"]) for k in "EVS")))
    add("Because validation was used in the last stage, its scores in this card are slightly optimistic. The test split in Phase 8 is the unbiased check. Full trial tables: `reports/training/tune_<E|V|S>_trials.csv`; stage-2 candidates: `tune_<E|V|S>_best.json`.\n")

    add("## 7. Training procedure and reproducibility\n")
    add(f"* `python src/training/train.py` reads `reports/training/tune_<k>_best.json`, verifies the split checksums, fits the preprocessor on the train rows, trains {len(params['E']['seeds'])} seeds per target with all CPU cores, "
        f"saves `<k>_seed<n>.ubj` (XGBoost native format, readable by later XGBoost versions), `preprocessor.json`, `params.json`, `intervals.json`, `checkpoint_manifest.json` (SHA-256 of every file, library versions, split checksums) and `logs/train.log`. Training took {man['training_seconds']} s.\n"
        "* **Run-to-run variation.** XGBoost's histogram trees are not bit-identical across seeds or thread counts. Single-fit validation WAPE across 8 seeds: "
        + "; ".join(f"{k} {noise[k]['seed_min']:.2f} to {noise[k]['seed_max']:.2f}" for k in "EVS")
        + ". The saved checkpoint is the reference; retraining reproduces it closely, not exactly. Loading the checkpoint is exact (`tests/test_training.py` reloads it and reproduces the saved validation predictions).\n"
        "* **Learning curves** (seed 42, `learning_curves.json`): validation RMSE of the log change is lowest at "
        + ", ".join(f"{int(pd.Series(curves[k]['validation_rmse']).idxmin()) + 1} of {len(curves[k]['validation_rmse'])} trees for {k}" for k in "EVS")
        + "; the difference to the final tree is at most "
        + f"{max(100 * (curves[k]['validation_rmse'][-1] / min(curves[k]['validation_rmse']) - 1) for k in 'EVS'):.1f}%, so there is no sign of late overfitting.\n")

    add("## 8. How to run the saved model\n")
    add("```python\nimport sys; sys.path.insert(0, 'src/training')\nfrom predict import Forecaster\nfc = Forecaster.load('models/xgboost_v1')\nout = fc.predict(frame)   # frame: rows in the data/splits layout\n```\n"
        "```bash\npython src/training/predict.py --split validation --out forecasts_validation.parquet\npython src/training/predict.py --input my_rows.parquet --out my_forecasts.parquet\n```\n"
        "Input columns: the features listed in `params.json` plus the base columns `last_E`, `sm3_V`, `sm6_S` and `horizon`. Output per target: `pred_<k>` (count), `lo90_<k>`, `hi90_<k>`, `pred_log_<k>`. "
        "Requirements: Python 3.13, `xgboost==%s`, `numpy==%s`, `pandas==%s`, `pyarrow` (see `requirements.txt`). The test split is refused unless `--unlock-test` is given (Phase 8). "
        "Producing features for a new origin beyond the data is a Phase 9 (deployment) task.\n" % (man["environment"]["xgboost"], man["environment"]["numpy"], man["environment"]["pandas"]))
    add("Rebuild from scratch: `python src/splits/make_splits.py`, then `python src/training/tune.py E|V|S`, `... --final-only`, `... --recent`, then `python src/training/train.py`, `check_preprocessing.py`, `compare_default.py`, `seed_noise.py`, `make_model_card.py`.\n")

    add("## 9. Validation results\n")
    add(f"Validation rows: {', '.join(f'{k} {met[k]['validation_rows']:,}' for k in 'EVS')}. Origins 2022-02 to 2022-11, horizons 1 to 10 (1 to 10 only, because the 10-month window ends before a 12-month horizon fits; horizons 11-12 are untested here).\n")
    add("### 9.1 WAPE % by horizon, model vs the best baseline (last value + seasonal shift)\n")
    hs = [str(h) for h in range(1, 11)]
    rows = []
    for k in "EVS":
        rows.append((f"{k} model", *[f"{met[k]['validation_wape_by_horizon'][h]:.1f}" for h in hs]))
        rows.append((f"{k} baseline", *[f"{met[k]['baselines']['last_plus_seasonal_shift']['by_horizon'][h]:.1f}" for h in hs]))
    add(table(["Series"] + [f"h={h}" for h in hs], rows))
    add("\n### 9.2 Other baselines and in-sample error (mean over horizons)\n")
    add(table(["Target", "Model", "Last value + seasonal shift", "Last value", "Seasonal naive + drift", "Model, in-sample (train rows)", "Pooled WAPE (all horizons together)"],
              [(k, f"{met[k]['validation_wape_mean_horizon']:.2f}", f"{met[k]['baselines']['last_plus_seasonal_shift']['mean_horizon']:.2f}", f"{met[k]['baselines']['last_value']['mean_horizon']:.2f}",
                f"{met[k]['baselines']['seasonal_naive_drift']['mean_horizon']:.2f}", f"{met[k]['train_wape_mean_horizon_in_sample']:.2f}", f"{met[k]['validation_wape_pooled']:.2f}") for k in "EVS"]))
    add("\n### 9.3 90% prediction intervals\n")
    add("Intervals are the model's predicted log level plus the 5% and 95% quantiles of its out-of-sample log errors in the three rolling-origin folds, by target and horizon (`intervals.json`). "
        "Coverage on the validation split: " + ", ".join(f"{k} {100 * met[k]['interval_90_validation_coverage']:.0f}%" for k in "EVS") + " against a nominal 90%. "
        "The intervals are too narrow for this window because errors in the post-COVID recovery are larger than in 2016-2019. They need recalibration (for example on a recent rolling window) before use; this is carried to Phase 8.\n")

    cE = ["Series_ID", "horizon", "last_E", "target_E", "shock_EV"]
    trE, vaE = sp.load_split("train", columns=cE), sp.load_split("validation", columns=cE)
    trE = trE[~trE.shock_EV]
    g_tr, g_va = float((trE.target_E - trE.last_E).mean()), float((vaE.target_E - vaE.last_E).mean())
    worse = {k: [h for h in range(1, 11) if met[k]["validation_wape_by_horizon"][str(h)] > met[k]["baselines"]["last_plus_seasonal_shift"]["by_horizon"][str(h)]] for k in "EVS"}
    add("## 10. Known weaknesses and open items\n")
    add("* **Regime shift in validation.** The validation window is the first ten months after COVID's end. Errors are about three times the in-sample errors for employed workers "
        f"({met['E']['validation_wape_mean_horizon']:.1f}% vs {met['E']['train_wape_mean_horizon_in_sample']:.1f}%), partly because employment grew much faster over the forecast horizon in this window "
        f"(mean log change {g_va:.3f}, against {g_tr:.3f} in the E training rows). The baseline suffers the same way, and the model still beats it on average, but validation accuracy is not a forecast of test accuracy.\n"
        "* **Where the baseline wins** (model error above the last-value-plus-seasonal-shift error), by horizon in months: "
        + "; ".join(f"{k}: {', '.join(map(str, v)) if v else 'none'}" for k, v in worse.items()) + ". The model is the better choice at longer horizons and for seekers.\n"
        "* **Seekers and the e-Shram ramp.** The whole validation window is inside the registry ramp (2021-08 to 2023-02), so seeker scores here mix model skill with a one-off structural change. The seasonal-naive-plus-drift baseline, which tracks year-on-year growth, "
        f"scores {met['S']['baselines']['seasonal_naive_drift']['mean_horizon']:.1f}% against the model's {met['S']['validation_wape_mean_horizon']:.1f}%: the margin over a simple baseline is only {100 * (1 - met['S']['validation_wape_mean_horizon'] / met['S']['baselines']['seasonal_naive_drift']['mean_horizon']):.0f}%, against {100 * (1 - met['S']['validation_wape_mean_horizon'] / met['S']['baselines']['last_plus_seasonal_shift']['mean_horizon']):.0f}% over last value plus seasonal shift. The Phase 6 concern that seekers beyond about 9 months lose to a simple baseline (D4) is **not resolved** and needs the post-ramp test months.\n"
        "* **Horizons 11-12** have no validation rows; they are covered only by the rolling-origin folds.\n"
        "* **Ten months of validation and fit-to-fit variation of 1-2%** mean that differences under about 2% between settings are ties. Tuning improved cross-validation by at most a few percent and did not beat the Phase 6 default on the most recent era for seekers.\n"
        "* **Intervals** under-cover (Section 9.3). **IT-ITeS vacancies and low-volume series** still need separate reporting (D5). Phase 1 accuracy thresholds are revisited in Phase 8.\n"
        "* **Trees cannot extrapolate** beyond the range of changes seen in training (for example a new structural break).\n")
    add("## 11. Files\n")
    add(table(["File", "Content"], [("`<E|V|S>_seed<42..46>.ubj`", "XGBoost models (15 files)"), ("`preprocessor.json`", "Train-fitted medians, means, standard deviations"), ("`params.json`", "All hyper-parameters, feature lists, base, seeds"),
                                    ("`intervals.json`", "Residual quantiles for the 90% interval"), ("`checkpoint_manifest.json`", "SHA-256 of every file, versions, split checksums, headline scores"),
                                    ("`logs/train.log`", "Execution log of the training run"), ("`model_card.md`", "This document")]))
    (M / "model_card.md").write_text("\n".join(L) + "\n", encoding="utf-8")
    print("wrote", M / "model_card.md")


